import itertools

def get_neighbors(r, c, n):
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            yield nr, nc

def count_good_paths(board, n):
    # board is a 2D list
    local_minima = []
    for r in range(n):
        for c in range(n):
            is_local_min = True
            for nr, nc in get_neighbors(r, c, n):
                if board[nr][nc] < board[r][c]:
                    is_local_min = False
                    break
            if is_local_min:
                local_minima.append((r, c))

    total_paths = 0
    for r_start, c_start in local_minima:
        # Use BFS/DFS to find all increasing paths starting from (r_start, c_start)
        # But it's just a simple recursion since the path must be increasing
        def count_increasing_paths(r, c):
            count = 1 # the path consisting of only (r, c)
            for nr, nc in get_neighbors(r, c, n):
                if board[nr][nc] > board[r][c]:
                    count += count_increasing_paths(nr, nc)
            return count

        # Wait, the recursion above is wrong because it counts paths multiple times?
        # No, it counts paths where each path is unique by its sequence of cells.
        # But wait, a path is a sequence of fields.
        # (r, c), (nr, nc), (nnr, nnc)...
        # The number of increasing paths starting at (r, c) is:
        # 1 + sum_{neighbor (nr, nc) with board[nr][nc] > board[r][c]} (number of increasing paths starting at (nr, nc))
        # This is exactly what the recursion does.

        # Let's use memoization for the recursion.
        memo = {}
        def count_inc_paths_memo(r, c):
            if (r, c) in memo:
                return memo[(r, c)]
            count = 1
            for nr, nc in get_neighbors(r, c, n):
                if board[nr][nc] > board[r][c]:
                    count += count_inc_paths_memo(nr, nc)
            memo[(r, c)] = count
            return count

        total_paths += count_inc_paths_memo(r_start, c_start)

    return total_paths

